function retryRandomnessPostProcessing(uint256 _requestId)
        public
        FunctionAdminRequired(this.retryRandomnessPostProcessing.selector)
    {
        (uint256 collectionId, uint256 tokenId, bytes32 derivedSeed, uint256 retryCount) =
